const PIZZA_HOT_API_URL = "https://script.google.com/macros/s/AKfycby5pD8nlMt62GdcAeHZKTj7cKF4xFOigK_Qhn7JV778mCIbwp0sO2eHKSnIt6TL57ZM/exec?api=PIZZA_HOT",
    PIZZA_HOT_API_URL_BK = "https://script.google.com/macros/s/AKfycbzApcrcbGcv5sM6o857xlJXzqp_yFg18VPKIVOShRzCeRouhqrK3Q5tgMHG3yXqZN91Pw/exec?api=PIZZA_HOT",
    PIZZA_HOT_CACHE_KEY = "pizza_hot_cache", PIZZA_HOT_CACHE_TIME_KEY = "pizza_hot_cache_time", PIZZA_HOT_CACHE_DURATION = 36e5,
    PIZZA_HOT_RETRY_DELAY = 1e3, PIZZA_HOT_LOADING_IMAGE = "assets/icon/loading.webp", pizzaElements = {};
let allPizzaOffers = [];

function handlePizzaReload() {
    clearPizzaCache(), loadPizzaOffers(!0)
}

async function loadPizzaOffers(e = !1) {
    setPizzaLoadingText("正在取得優惠資料..."), setPizzaState("loading");
    try {
        if (!e) {
            const e = getValidPizzaCache();
            if (null !== e) return console.log("Pizza Hot 使用本機快取資料"), allPizzaOffers = e.filter(isValidPizzaOffer), void renderPizzaOffers(allPizzaOffers, !1)
        }
        const t = await fetchPizzaDataWithBackup();
        t.length > 0 ? savePizzaCache(t) : clearPizzaCache(), allPizzaOffers = t.filter(isValidPizzaOffer), renderPizzaOffers(allPizzaOffers, !1)
    } catch (e) {
        console.error("Pizza Hot API 四次連線皆失敗", e), setPizzaState("error")
    }
}

async function fetchPizzaDataWithBackup() {
    let e = null;
    try {
        return setPizzaLoadingText("正在取得優惠資料..."), await fetchPizzaApi(PIZZA_HOT_API_URL, "Pizza Hot 主要 API 第一次連線")
    } catch (t) {
        e = t, console.warn("Pizza Hot 主要 API 第一次連線失敗", t)
    }
    setPizzaLoadingText("第二次連線嘗試..."), await waitPizzaRetry(1e3);
    try {
        return await fetchPizzaApi(PIZZA_HOT_API_URL, "Pizza Hot 主要 API 第二次連線")
    } catch (t) {
        e = t, console.warn("Pizza Hot 主要 API 第二次連線失敗", t)
    }
    setPizzaLoadingText("第三次連線嘗試..."), await waitPizzaRetry(1e3);
    try {
        return await fetchPizzaApi(PIZZA_HOT_API_URL_BK, "Pizza Hot 備援 API 第一次連線")
    } catch (t) {
        e = t, console.error("Pizza Hot 備援 API 第一次連線失敗", t)
    }
    setPizzaLoadingText("第四次連線嘗試..."), await waitPizzaRetry(1e3);
    try {
        return await fetchPizzaApi(PIZZA_HOT_API_URL_BK, "Pizza Hot 備援 API 第二次連線")
    } catch (t) {
        e = t, console.error("Pizza Hot 備援 API 第二次連線失敗", t)
    }
    throw e || new Error("Pizza Hot API 連線失敗")
}

async function fetchPizzaApi(e, t) {
    console.log(`${t}${e}`);
    const a = await fetch(e, {method: "GET", redirect: "follow", cache: "no-store"});
    if (!a.ok) throw new Error(`${t} HTTP ${a.status}`);
    const i = await a.json();
    if (!Array.isArray(i)) throw new Error(`${t}回傳格式不是陣列`);
    return i
}

function getValidPizzaCache() {
    const e = localStorage.getItem("pizza_hot_cache"), t = localStorage.getItem("pizza_hot_cache_time");
    if (!e || !t) return null;
    const a = Date.now() - Number(t);
    if (!Number.isFinite(a) || a < 0 || a >= 36e5) return clearPizzaCache(), null;
    try {
        const t = JSON.parse(e);
        return Array.isArray(t) && 0 !== t.length ? t : (console.log("Pizza Hot 本機快取為空重新呼叫 API"), clearPizzaCache(), null)
    } catch (e) {
        return console.warn("Pizza Hot 本機快取無法解析重新呼叫 API", e), clearPizzaCache(), null
    }
}

function savePizzaCache(e) {
    if (Array.isArray(e) && 0 !== e.length) try {
        localStorage.setItem("pizza_hot_cache", JSON.stringify(e)), localStorage.setItem("pizza_hot_cache_time", String(Date.now()))
    } catch (e) {
        console.warn("Pizza Hot 本機快取寫入失敗", e)
    } else clearPizzaCache()
}

function clearPizzaCache() {
    localStorage.removeItem("pizza_hot_cache"), localStorage.removeItem("pizza_hot_cache_time")
}

function createPizzaLoadingContent() {
    if (!pizzaElements.loading) return;
    pizzaElements.loading.replaceChildren();
    const e = document.createElement("img");
    e.src = PIZZA_HOT_LOADING_IMAGE, e.alt = "", e.className = "pizza-loading__image", e.setAttribute("aria-hidden", "true");
    const t = document.createElement("span");
    t.className = "pizza-loading__text", t.textContent = "正在取得優惠資料...", pizzaElements.loading.append(e, t), pizzaElements.loading.setAttribute("role", "status"), pizzaElements.loading.setAttribute("aria-live", "polite"), pizzaElements.loadingText = t
}

function setPizzaLoadingText(e) {
    pizzaElements.loadingText || createPizzaLoadingContent(), pizzaElements.loadingText && (pizzaElements.loadingText.textContent = e), pizzaElements.count && !pizzaElements.loading?.hidden && (pizzaElements.count.textContent = e)
}

function waitPizzaRetry(e) {
    return new Promise(t => {
        window.setTimeout(t, e)
    })
}

function isValidPizzaOffer(e) {
    return e && "object" == typeof e && Boolean(e.code) && Boolean(e.detail)
}

function filterPizzaOffers() {
    const e = pizzaElements.search.value.trim().toLocaleLowerCase("zh-Hant-TW");
    if (!e) return void renderPizzaOffers(allPizzaOffers, !1);
    renderPizzaOffers(allPizzaOffers.filter(t => String(t.detail).toLocaleLowerCase("zh-Hant-TW").includes(e)), !0)
}

function renderPizzaOffers(e, t) {
    if (pizzaElements.grid.replaceChildren(), 0 === e.length) return pizzaElements.count.textContent = t ? "找不到符合條件的優惠" : "目前沒有優惠資料", void setPizzaState("empty");
    const a = document.createDocumentFragment();
    e.forEach(e => {
        const t = document.createElement("article");
        t.className = "pizza-card";
        const i = document.createElement("p");
        i.className = "pizza-card__code", i.textContent = `優惠代碼 ${String(e.code)}`;
        const n = document.createElement("p");
        n.className = "pizza-card__detail", n.textContent = String(e.detail);
        const z = document.createElement("p");
        z.className = "pizza-card__date", z.textContent = e.endDate ? `優惠截止日期${formatPizzaDate(e.endDate)}` : "優惠截止日期未提供", t.append(i, n, z), a.append(t)
    }), pizzaElements.grid.append(a), pizzaElements.count.textContent = t ? `找到 ${e.length} 組優惠` : `目前共有 ${e.length} 組優惠`, setPizzaState("success")
}

function formatPizzaDate(e) {
    const t = String(e).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return t ? `${t[1]}/${t[2]}/${t[3]}` : String(e)
}

function setPizzaState(e) {
    pizzaElements.loading.hidden = "loading" !== e, pizzaElements.error.hidden = "error" !== e, pizzaElements.empty.hidden = "empty" !== e, pizzaElements.reload.hidden = "error" !== e;
    const t = "loading" === e || "error" === e;
    pizzaElements.search.disabled = t, "loading" === e && (pizzaElements.grid.replaceChildren(), pizzaElements.loadingText ? pizzaElements.count.textContent = pizzaElements.loadingText.textContent : pizzaElements.count.textContent = "正在取得優惠資料..."), "error" === e && (pizzaElements.grid.replaceChildren(), pizzaElements.count.textContent = "優惠資料載入失敗")
}

document.addEventListener("DOMContentLoaded", () => {
    pizzaElements.search = document.querySelector("#pizza-search"), pizzaElements.grid = document.querySelector("#pizza-card-grid"), pizzaElements.loading = document.querySelector("#pizza-loading"), pizzaElements.error = document.querySelector("#pizza-error"), pizzaElements.empty = document.querySelector("#pizza-empty"), pizzaElements.count = document.querySelector("#pizza-result-count"), pizzaElements.reload = document.querySelector("#pizza-reload"), createPizzaLoadingContent(), pizzaElements.search.addEventListener("input", filterPizzaOffers), pizzaElements.reload.addEventListener("click", handlePizzaReload), loadPizzaOffers()
});